        IntervalDomain.State a = createState("x", BigInteger.ONE, BigInteger.valueOf(3));
        IntervalDomain.State b = createState("x", BigInteger.ONE, BigInteger.valueOf(5));
        IntervalDomain.State result = domain.widen(a, b);

