reply.reasoning:
The user wants me to write an abstract domain for a program analysis engine. This is a backward reachability analysis where:

1. The analysis starts at a `reach(id)` call (the target)
2. It works backward through the program
3. The target starts at `top()` and all other locations start at `bottom()`
4. For each step from location A to B, it computes `transfer(step, state at B)` and joins into state at A
5. A target is proved unreachable when the state at method entry is `bottom()`

I need to implement a domain that:
1. Tracks information about program variables
2. Is sound (never excludes a program state it cannot rule out)
3. Can prove some `reach()` calls unreachable

For a simple but effective domain, I'll implement an **interval domain** that tracks ranges of values for each local variable. This is a classic abstract domain that can prove many programs unreachable while being sound.

Let me think about what the domain needs to track:
- Each local variable maps to an interval [min, max] (possibly unbounded)
- `top()` admits all states (all intervals are [-∞, +∞])
- `bottom()` admits no states (special bottom value)
- `entails(a, b)` checks if every state admitted by `a` is also admitted by `b`
- `join(a, b)` takes the union of intervals
- `widen(a, b)` accelerates convergence at loops

For the transfer function in backward analysis:
- `Assign(x, e)`: The constraint on x in `post` becomes a constraint on e. x itself is unconstrained before.
- `Assume(c)`: Restrict `post` to states where c holds
- `Call(x, randInt, [])`: x gets an arbitrary integer, so x is unconstrained in the result

Let me design the State class:
- A Map from variable name to Interval (min, max, both BigInteger or null for unbounded)


- Need a special BOTTOM state

For intervals:
- `null` for min means -∞
- `null` for max means +∞
- Both null means unbounded interval
- A separate BOTTOM marker for when no states are admitted

Let me write the implementation:

```java
package pag.domains.gen;

import java.math.BigInteger;
import java.util.*;
import pag.api.*;

public class IntervalDomain implements Domain<IntervalDomain.State> {

    public static final class State {
        private final Map<String, Interval> intervals;
        private final boolean isBottom;

        private static final Map<String, Interval> EMPTY = Collections.emptyMap();

        private State(Map<String, Interval> intervals, boolean isBottom) {
            this.intervals = isBottom ? EMPTY : Map.copyOf(intervals);
            this.isBottom = isBottom;
        }

        public static State bottom() {
            return new State(EMPTY, true);
        }

        public static State top() {
            return new State(new HashMap<>(), false);
        }

        public static State fromMap(Map<String, Interval> intervals) {
            return new State(intervals, false);
        }

        public boolean isBottom() {
            return isBottom;
        }

        public Interval getInterval(String var) {
            if (isBottom) return Interval.BOTTOM;
            return intervals.getOrDefault(var, Interval.TOP);
        }

        public Map<String, Interval> getIntervals() {
            return intervals;
        }
    }

    public static final class Interval {
        private final BigInteger min;
        private final BigInteger max;
        private final boolean isBottom;

        private static final Interval BOTTOM = new Interval(null, null, true);
        private static final Interval TOP = new Interval(null, null, false);

        public Interval(BigInteger min, BigInteger max, boolean isBottom) {
            this.min = min;
            this.max = max;
            this.isBottom = isBottom;
        }

        public static Interval bottom() {
            return BOTTOM;
        }

        public static Interval top() {
            return TOP;
        }

        public static Interval of(BigInteger min, BigInteger max) {
            if (min != null && max != null && min.compareTo(max) > 0) {
                return BOTTOM;
            }
            return new Interval(min, max, false);
        }

        public boolean isBottom() {
            return isBottom;
        }

        public boolean isTop() {
            return !isBottom && min == null && max == null;
        }

        public BigInteger getMin() {
            return min;
        }

        public BigInteger getMax() {
            return max;
        }

        public Interval join(Interval other) {
            if (this.isBottom()) return other;
            if (other.isBottom()) return this;
            if (this.isTop() || other.isTop()) return TOP;

            BigInteger newMin = (this.min == null || other.min == null) ? null :
                this.min.compareTo(other.min) <= 0 ? this.min : other.min;
            BigInteger newMax = (this.max == null || other.max == null) ? null :
                this.max.compareTo(other.max) >= 0 ? this.max : other.max;

            return of(newMin, newMax);
        }

        public Interval widen(Interval other) {
            if (this.isBottom()) return other;
            if (other.isBottom()) return this;
            if (this.isTop() || other.isTop()) return TOP;

            BigInteger newMin, newMax;

            // Widening: if the bound is expanding, make it unbounded
            if (this.min != null && other.min != null) {
                if (other.min.compareTo(this.min) < 0) {
                    newMin = null; // Widening to -∞
                } else {
                    newMin = this.min;
                }
            } else {
                newMin = null;
            }

            if (this.max != null && other.max != null) {
                if (other.max.compareTo(this.max) > 0) {
                    newMax = null; // Widening to +∞
                } else {
                    newMax = this.max;
                }
            } else {
                newMax = null;
            }

            return of(newMin, newMax);
        }

        public boolean entails(Interval other) {
            // this ⊆ other
            if (this.isBottom()) return true;
            if (other.isBottom()) return false;
            if (other.isTop()) return true;
            if (this.isTop()) return false;

            // Check min: this.min >= other.min
            if (other.min != null && this.min != null) {
                if (this.min.compareTo(other.min) < 0) return false;
            } else if (other.min != null && this.min == null) {
                return false; // this has -∞, other doesn't
            }

            // Check max: this.max <= other.max
            if (other.max != null && this.max != null) {
                if (this.max.compareTo(other.max) > 0) return false;
            } else if (other.max != null && this.max == null) {
                return false; // this has +∞, other doesn't
            }

            return true;
        }

        // For backward transfer: given post-interval on x, what interval on e?
        // For Assign(x, e): post's constraint on x becomes constraint on e
        // x itself is unconstrained before
        public Interval inverseAssign(Interval postInterval) {
            // In backward analysis, the constraint on x after the assignment
            // becomes a constraint on e before the assignment
            return postInterval;
        }

        // For Assume with comparison
        public Interval assumeEq(BigInteger value) {
            if (isBottom()) return BOTTOM;
            if (isTop()) return of(value, value);

            if (min != null && max != null) {
                if (value.compareTo(min) >= 0 && value.compareTo(max) <= 0) {
                    return of(value, value);
                }
                return BOTTOM;
            } else if (min != null) {
                if (value.compareTo(min) >= 0) {
                    return of(value, value);
                }
                return BOTTOM;
            } else if (max != null) {
                if (value.compareTo(max) <= 0) {
                    return of(value, value);
                }
                return BOTTOM;
            }
            return of(value, value);
        }

        public Interval assumeNe(BigInteger value) {
            if (isBottom()) return BOTTOM;
            if (isTop()) return TOP;

            if (min != null && max != null && min.equals(max) && min.equals(value)) {
                return BOTTOM;
            }

            // For simplicity, we'll return the same interval
            // A more precise implementation would split the interval
            return this;
        }

        public Interval assumeLt(BigInteger value) {
            if (isBottom()) return BOTTOM;
            if (isTop()) return of(null, value.subtract(BigInteger.ONE));

            if (max != null && max.compareTo(value) >= 0) {
                BigInteger newMax = value.subtract(BigInteger.ONE);
                if (min != null && min.compareTo(newMax) > 0) {
                    return BOTTOM;
                }
                return of(min, newMax);
            }
            return this;
        }

        public Interval assumeLe(BigInteger value) {
            if (isBottom()) return BOTTOM;
            if (isTop()) return of(null, value);

            if (max != null && max.compareTo(value) > 0) {
                BigInteger newMax = value;
                if (min != null && min.compareTo(newMax) > 0) {
                    return BOTTOM;
                }
                return of(min, newMax);
            }
            return this;
        }

        public Interval assumeGt(BigInteger value) {
            if (isBottom()) return BOTTOM;
            if (isTop()) return of(value.add(BigInteger.ONE), null);

            if (min != null && min.compareTo(value) <= 0) {
                BigInteger newMin = value.add(BigInteger.ONE);
                if (max != null && newMin.compareTo(max) > 0) {
                    return BOTTOM;
                }
                return of(newMin, max);
            }
            return this;
        }

        public Interval assumeGe(BigInteger value) {
            if (isBottom()) return BOTTOM;
            if (isTop()) return of(value, null);

            if (min != null && min.compareTo(value) < 0) {
                BigInteger newMin = value;
                if (max != null && newMin.compareTo(max) > 0) {
                    return BOTTOM;
                }
                return of(newMin, max);
            }
            return this;
        }

        @Override
        public String toString() {
            if (isBottom()) return "⊥";
            if (isTop()) return "⊤";
            return "[" + (min == null ? "-∞" : min) + ", " + (max == null ? "+∞" : max) + "]";
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Interval)) return false;
            Interval other = (Interval) obj;
            return isBottom == other.isBottom &&
                   Objects.equals(min, other.min) &&
                   Objects.equals(max, other.max);
        }

        @Override
        public int hashCode() {
            return Objects.hash(isBottom, min, max);
        }
    }

    public IntervalDomain() {
    }

    @Override
    public String name() {
        return "IntervalDomain";
    }

    @Override
    public State top() {
        return State.top();
    }

    @Override
    public State bottom() {
        return State.bottom();
    }

    @Override
    public boolean isBottom(State s) {
        return s.isBottom();
    }

    @Override
    public boolean entails(State a, State b) {
        if (a.isBottom()) return true;
        if (b.isBottom()) return false;

        // For every variable in a, check that a's interval entails b's interval
        for (Map.Entry<String, Interval> entry : a.getIntervals().entrySet()) {
            Interval aInt = entry.getValue();
            Interval bInt = b.getInterval(entry.getKey());
            if (!aInt.entails(bInt)) {
                return false;
            }
        }
        return true;
    }

    @Override
    public State join(State a, State b) {
        if (a.isBottom()) return b;
        if (b.isBottom()) return a;

        Map<String, Interval> result = new HashMap<>(a.getIntervals());

        for (Map.Entry<String, Interval> entry : b.getIntervals().entrySet()) {
            String var = entry.getKey();
            Interval aInt = a.getInterval(var);
            Interval bInt = entry.getValue();
            result.put(var, aInt.join(bInt));
        }

        return State.fromMap(result);
    }

    @Override
    public State widen(State a, State b) {
        if (a.isBottom()) return b;
        if (b.isBottom()) return a;

        Map<String, Interval> result = new HashMap<>(a.getIntervals());

        for (Map.Entry<String, Interval> entry : b.getIntervals().entrySet()) {
            String var = entry.getKey();
            Interval aInt = a.getInterval(var);
            Interval bInt = entry.getValue();
            result.put(var, aInt.widen(bInt));
        }

        return State.fromMap(result);
    }

    @Override
    public State transfer(Step step, State post) {
        if (post.isBottom()) {
            return State.bottom();
        }

        switch (step) {
            case Step.Assign assign -> {
                return transferAssign(assign, post);
            }
            case Step.Assume assume -> {
                return transferAssume(assume, post);
            }
            case Step.Call call -> {
                return transferCall(call, post);
            }
        }
        throw new UnsupportedOperationException("Unknown step type");
    }

    private State transferAssign(Step.Assign assign, State post) {
        // Backward transfer: post's constraint on x becomes constraint on e
        // x itself is unconstrained before (can be anything)
        String varName = assign.target().name();
        RVal source = assign.source();

        // Evaluate the source expression in the post state
        Interval sourceInterval = evaluateRVal(source, post);

        // Get post's constraint on the target variable
        Interval targetPostInterval = post.getInterval(varName);

        // The constraint on x after the assignment becomes a constraint on the source
        // Before the assignment, x can be anything (TOP)
        Map<String, Interval> result = new HashMap<>(post.getIntervals());

        // For the target variable, it's unconstrained before the assignment
        // But we need to check if the source expression can satisfy the post constraint
        if (sourceInterval.isBottom()) {
            // Source can never produce a value satisfying post constraint
            return State.bottom();
        }

        // Remove the target variable's constraint (it's unconstrained before)
        result.remove(varName);

        return State.fromMap(result);
    }

    private State transferAssume(Step.Assume assume, State post) {
        // Backward transfer: restrict post to states where cond holds
        RVal cond = assume.cond();

        // For simplicity, handle comparison conditions
        if (cond instanceof RVal.Binop binop) {
            return transferAssumeBinop(binop, post);
        }

        // For other conditions, we return post (lose precision)
        return post;
    }

    private State transferAssumeBinop(RVal.Binop binop, State post) {
        BinOp op = binop.op();
        RVal l = binop.l();
        RVal r = binop.r();

        Interval lInt = evaluateRVal(l, post);
        Interval rInt = evaluateRVal(r, post);

        // For simplicity, handle cases where at least one side is a constant
        if (l instanceof RVal.IntConst) {
            // l is constant, r is variable or constant
            BigInteger lVal = ((RVal.IntConst) l).v();
            if (r instanceof LVal.Local local) {
                String varName = local.name();
                Interval varInt = post.getInterval(varName);
                Interval newInt = applyComparisonToVar(varInt, op, lVal, rInt);
                Map<String, Interval> result = new HashMap<>(post.getIntervals());
                result.put(varName, newInt);
                return State.fromMap(result);
            }
        } else if (r instanceof RVal.IntConst) {
            // r is constant, l is variable or constant
            BigInteger rVal = ((RVal.IntConst) r).v();
            if (l instanceof LVal.Local local) {
                String varName = local.name();
                Interval varInt = post.getInterval(varName);
                Interval newInt = applyComparisonToVar(varInt, op, rVal, lInt, true);
                Map<String, Interval> result = new HashMap<>(post.getIntervals());
                result.put(varName, newInt);
                return State.fromMap(result);
            }
        }

        // For complex expressions, lose precision and return post
        return post;
    }

    private Interval applyComparisonToVar(Interval varInt, BinOp op, BigInteger constant, Interval otherInt) {
        return applyComparisonToVar(varInt, op, constant, otherInt, false);
    }

    private Interval applyComparisonToVar(Interval varInt, BinOp op, BigInteger constant, Interval otherInt, boolean swapped) {
        switch (op) {
            case Eq:
                if (swapped) {
                    return varInt.assumeEq(constant);
                } else {
                    return varInt.assumeEq(constant);
                }
            case Ne:
                if (swapped) {
                    return varInt.assumeNe(constant);
                } else {
                    return varInt.assumeNe(constant);
                }
            case Lt:
                if (swapped) {
                    // var < constant means otherInt > var
                    return varInt.assumeLt(constant);
                } else {
                    return varInt.assumeLt(constant);
                }
            case Le:
                if (swapped) {
                    return varInt.assumeLe(constant);
                } else {
                    return varInt.assumeLe(constant);
                }
            case Gt:
                if (swapped) {
                    return varInt.assumeGt(constant);
                } else {
                    return varInt.assumeGt(constant);
                }
            case Ge:
                if (swapped) {
                    return varInt.assumeGe(constant);
                } else {
                    return varInt.assumeGe(constant);
                }
            default:
                return varInt;
        }
    }

    private State transferCall(Step.Call call, State post) {
        // For randInt(), the target variable gets an arbitrary integer
        // In backward analysis, this means the target is unconstrained
        if (call.target().isPresent()) {
            String varName = call.target().get().name();
            Map<String, Interval> result = new HashMap<>(post.getIntervals());
            result.remove(varName); // Unconstrained
            return State.fromMap(result);
        }
        return post;
    }

    private Interval evaluateRVal(RVal rval, State state) {
        switch (rval) {
            case RVal.IntConst constVal -> {
                return Interval.of(constVal.v(), constVal.v());
            }
            case RVal.Binop binop -> {
                return evaluateBinop(binop, state);
            }
            case LVal.Local local -> {
                return state.getInterval(local.name());
            }
            case LVal.StaticField field -> {
                // For static fields, return TOP (lose precision)
                return Interval.TOP;
            }
        }
        throw new UnsupportedOperationException("Unknown RVal type");
    }

    private Interval evaluateBinop(RVal.Binop binop, State state) {
        BinOp op = binop.op();
        RVal l = binop.l();
        RVal r = binop.r();

        Interval lInt = evaluateRVal(l, state);
        Interval rInt = evaluateRVal(r, state);

        switch (op) {
            case Add:
                return addIntervals(lInt, rInt);
            case Sub:
                return subIntervals(lInt, rInt);
            case Mult:
                return multIntervals(lInt, rInt);
            case Lt, Le, Gt, Ge, Eq, Ne:
                // For comparisons, return [0, 1] (boolean result)
                // Or more precisely, we could track if it's always true/false
                return Interval.of(BigInteger.ZERO, BigInteger.ONE);
            default:
                return Interval.TOP;
        }
    }

    private Interval addIntervals(Interval a, Interval b) {
        if (a.isBottom() || b.isBottom()) return Interval.BOTTOM;
        if (a.isTop() || b.isTop()) return Interval.TOP;

        BigInteger min = null, max = null;

        if (a.getMin() != null && b.getMin() != null) {
            min = a.getMin().add(b.getMin());
        }
        if (a.getMax() != null && b.getMax() != null) {
            max = a.getMax().add(b.getMax());
        }

        return Interval.of(min, max);
    }

    private Interval subIntervals(Interval a, Interval b) {
        if (a.isBottom() || b.isBottom()) return Interval.BOTTOM;
        if (a.isTop() || b.isTop()) return Interval.TOP;

        BigInteger min = null, max = null;

        if (a.getMin() != null && b.getMax() != null) {
            min = a.getMin().subtract(b.getMax());
        }
        if (a.getMax() != null && b.getMin() != null) {
            max = a.getMax().subtract(b.getMin());
        }

        return Interval.of(min, max);
    }

    private Interval multIntervals(Interval a, Interval b) {
        if (a.isBottom() || b.isBottom()) return Interval.BOTTOM;
        if (a.isTop() || b.isTop()) return Interval.TOP;

        List<BigInteger> candidates = new ArrayList<>();
        for (BigInteger valA : new BigInteger[]{a.getMin(), a.getMax()}) {
            for (BigInteger valB : new BigInteger[]{b.getMin(), b.getMax()}) {
                if (valA != null && valB != null) {
                    candidates.add(valA.multiply(valB));
                }
            }
        }

        if (candidates.isEmpty()) {
            return Interval.TOP;
        }

        BigInteger min = Collections.min(candidates);
        BigInteger max = Collections.max(candidates);

        return Interval.of(min, max);
    }

    @Override
    public String toString() {
        return "IntervalDomain";
    }
}
